+use std::path::Path;
+
+struct GlobMatcher {
+    pattern: glob::Pattern,
+}
+
+impl GlobMatcher {
+    fn new(base: &str, pattern: &str) -> crate::Result<Self> {
+        let full_pattern = full_pattern(base, pattern);
+        let pattern = glob::Pattern::new(&full_pattern)
+            .map_err(|err| crate::Error::context("Invalid glob pattern", err))?;
+        Ok(Self { pattern })
+    }
+
+    fn match_paths(&self, candidate_paths: &[String]) -> Vec<String> {
+        candidate_paths
+            .iter()
+            .filter(|path| self.pattern.matches_with(path, match_options()))
+            .cloned()
+            .collect()
+    }
+}
+
+pub(crate) fn match_glob(
+    base: &str,
+    pattern: &str,
+    candidate_paths: &[String],
+) -> crate::Result<Vec<String>> {
+    Ok(GlobMatcher::new(base, pattern)?.match_paths(candidate_paths))
+}
+
+pub(crate) fn traversal_root(base: &str, pattern: &str) -> String {
+    let full_pattern = full_pattern(base, pattern);
+    literal_traversal_root(&full_pattern)
+}
+
+pub(crate) fn join_path(base: &str, path: &str) -> String {
+    if path.is_empty() {
+        return base.to_string();
+    }
+    if is_absolute(path) {
+        return path.to_string();
+    }
+    if base.is_empty() {
+        return path.to_string();
+    }
+    if base == "/" {
+        return format!("/{path}");
+    }
+    format!("{}/{}", base.trim_end_matches('/'), path)
+}
+
+fn full_pattern(base: &str, pattern: &str) -> String {
+    if is_absolute(pattern) {
+        pattern.to_string()
+    } else {
+        join_path(base, pattern)
+    }
+}
+
+fn is_absolute(path: &str) -> bool {
+    path.starts_with('/') || Path::new(path).is_absolute()
+}
+
+fn match_options() -> glob::MatchOptions {
+    glob::MatchOptions {
+        case_sensitive:              true,
+        require_literal_separator:   true,
+        require_literal_leading_dot: false,
+    }
+}
+
+fn literal_traversal_root(pattern: &str) -> String {
+    let absolute = pattern.starts_with('/');
+    let mut literal_segments = Vec::new();
+    let mut saw_meta = false;
+
+    for segment in pattern.split('/').filter(|segment| !segment.is_empty()) {
+        if has_glob_meta(segment) {
+            saw_meta = true;
+            break;
+        }
+        literal_segments.push(segment);
+    }
+
+    if saw_meta {
+        return build_path(absolute, &literal_segments);
+    }
+
+    parent_path(&build_path(absolute, &literal_segments))
+}
+
+fn has_glob_meta(segment: &str) -> bool {
+    segment
+        .chars()
+        .any(|character| matches!(character, '*' | '?' | '['))
+}
+
+fn build_path(absolute: bool, segments: &[&str]) -> String {
+    if segments.is_empty() {
+        return if absolute {
+            "/".to_string()
+        } else {
+            ".".to_string()
+        };
+    }
+
+    let joined = segments.join("/");
+    if absolute {
+        format!("/{joined}")
+    } else {
+        joined
+    }
+}
+
+fn parent_path(path: &str) -> String {
+    if path == "/" {
+        return "/".to_string();
+    }
+
+    let trimmed = path.trim_end_matches('/');
+    if trimmed.is_empty() {
+        return ".".to_string();
+    }
+
+    match trimmed.rfind('/') {
+        Some(0) => "/".to_string(),
+        Some(index) => trimmed[..index].to_string(),
+        None => ".".to_string(),
+    }
+}
